    stp   x15, x16, [sp, #48]

    // [x19:x20, x11:x17] <- z = b1 x a1_0
    ldp   x3, x4, [x2, #64]
    ldp   x5, x6, [x2, #80]
    ldp   x7, x8, [x2, #96]
    ldp   x9, x10, [x2, #112]
    add   x1, x1, #64                // a1; x1 is dead after P1
    ldr   x21, [x1]
    MUL64x512  x19,x20,x11,x12,x13,x14,x15,x16,x17, x3,x4,x5,x6,x7,x8,x9,x10, x21, x22
    FPMUL512x512  x1, x3,x4,x5,x6,x7,x8,x9,x10, x19,x20,x11,x12,x13,x14,x15,x16,x17, x21, x22

    // c0 = u - P1 -> x3..x10 ; c1 = w - P1 -> x17,x19,x20,x11..x15 (in place)
    ldp   x21, x22, [sp, #64]
    subs  x3, x21, x17
    sbcs  x4, x22, x19
    ldp   x21, x22, [sp, #80]
    sbcs  x5, x21, x20
    sbcs  x6, x22, x11
    ldp   x21, x22, [sp, #96]
    sbcs  x7, x21, x12
    sbcs  x8, x22, x13
    ldp   x21, x22, [sp, #112]
    sbcs  x9, x21, x14
    sbc   x10, x22, x15
    ldp   x21, x22, [sp]
    subs  x17, x21, x17
    sbcs  x19, x22, x19
    ldp   x21, x22, [sp, #16]
    sbcs  x20, x21, x20
    sbcs  x11, x22, x11
    ldp   x21, x22, [sp, #32]
    sbcs  x12, x21, x12
    sbcs  x13, x22, x13
    ldp   x21, x22, [sp, #48]
    sbcs  x14, x21, x14
    sbc   x15, x22, x15
    movn  x16, #0xfe50, lsl #48      // p[7] = 0x01AFFFFFFFFFFFFF
    // c0 pass 1/2
    lsr   x21, x10, #57
    neg   x21, x21
    asr   x21, x21, #63
    and   x22, x16, x21
    subs  x3, x3, x21
    sbcs  x4, x4, x21
    sbcs  x5, x5, x21
    sbcs  x6, x6, x21
    sbcs  x7, x7, x21
    sbcs  x8, x8, x21
    sbcs  x9, x9, x21
    sbc   x10, x10, x22
    // c0 pass 2/2
    lsr   x21, x10, #57
    neg   x21, x21
    asr   x21, x21, #63
    and   x22, x16, x21
    subs  x3, x3, x21
    sbcs  x4, x4, x21
    sbcs  x5, x5, x21
    sbcs  x6, x6, x21
    sbcs  x7, x7, x21
    sbcs  x8, x8, x21
    sbcs  x9, x9, x21
    sbc   x10, x10, x22
    // c1 pass 1/2
    lsr   x21, x15, #57
    neg   x21, x21
    asr   x21, x21, #63
    and   x22, x16, x21
    subs  x17, x17, x21
    sbcs  x19, x19, x21
    sbcs  x20, x20, x21
    sbcs  x11, x11, x21
    sbcs  x12, x12, x21
    sbcs  x13, x13, x21
    sbcs  x14, x14, x21
    sbc   x15, x15, x22
    // c1 pass 2/2
    lsr   x21, x15, #57
    neg   x21, x21
    asr   x21, x21, #63
    and   x22, x16, x21
    subs  x17, x17, x21
    sbcs  x19, x19, x21
    sbcs  x20, x20, x21
    sbcs  x11, x11, x21
    sbcs  x12, x12, x21
    sbcs  x13, x13, x21
    sbcs  x14, x14, x21
    sbc   x15, x15, x22

    stp   x3, x4, [x0]
    stp   x5, x6, [x0, #16]
    stp   x7, x8, [x0, #32]
    stp   x9, x10, [x0, #48]
    stp   x17, x19, [x0, #64]
    stp   x20, x11, [x0, #80]
    stp   x12, x13, [x0, #96]
    stp   x14, x15, [x0, #112]
    ldp   x21, x22, [sp, #144]
    ldp   x19, x20, [sp, #128]
    add   sp, sp, #160
    ret

//***********************************************************************
//  Squaring in GF(p^2), both components
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//  Inputs: a = [a1, a0] stored in [x1]
//  Output: c = [c1, c0] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+2p, then a1) = x3..x10;
//                       acc z0..z8 = x11..x17,x19,x20,
//                       scalar bi = x21, MULADD temp x22;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 64) holds s = a0+a1 (raw);
//         [sp+64 .. 128) holds t = 2*a0 (raw; self-add, EXTR is slow).
//***********************************************************************
.global fp2_sqr
.p2align 6
fp2_sqr:
    sub   sp, sp, #160               // 128 for s + t buffer + 32 for callee saves
    stp   x19, x20, [sp, #128]
    stp   x21, x22, [sp, #144]

    // t = 2*a0 (raw) -> [sp+64] ; a0 stays in x3..x10
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    adds  x11, x3, x3
    adcs  x12, x4, x4
    adcs  x13, x5, x5
    adcs  x14, x6, x6
    adcs  x15, x7, x7
    adcs  x16, x8, x8
    adcs  x17, x9, x9
    adc   x19, x10, x10
    stp   x11, x12, [sp, #64]
    stp   x13, x14, [sp, #80]
    stp   x15, x16, [sp, #96]
    stp   x17, x19, [sp, #112]
    // s = a0 + a1 (raw) -> [sp]
    ldp   x11, x12, [x1, #64]
    ldp   x13, x14, [x1, #80]
    ldp   x15, x16, [x1, #96]
    ldp   x17, x19, [x1, #112]
    adds  x11, x11, x3
    adcs  x12, x4, x12
    adcs  x13, x5, x13
    adcs  x14, x6, x14
    adcs  x15, x7, x15
    adcs  x16, x8, x16
    adcs  x17, x9, x17
    adc   x19, x19, x10
    stp   x11, x12, [sp]
    stp   x13, x14, [sp, #16]
    stp   x15, x16, [sp, #32]
    stp   x17, x19, [sp, #48]
    // d = a0 - a1 + 2p (raw) -> x3..x10 ; p2 = 2p = {-2,-1,...,0x035FFFFFFFFFFFFF}
    ldp   x11, x12, [x1, #64]
    subs  x3, x3, x11
    sbcs  x4, x4, x12
    ldp   x11, x12, [x1, #80]
    sbcs  x5, x5, x11
    sbcs  x6, x6, x12
    ldp   x11, x12, [x1, #96]
    sbcs  x7, x7, x11
    sbcs  x8, x8, x12
    ldp   x11, x12, [x1, #112]
    sbcs  x9, x9, x11
    sbcs  x10, x10, x12
    mov   x11, #-2
    adds  x3, x3, x11
    mov   x11, #-1
    adcs  x4, x4, x11
    adcs  x5, x5, x11
    adcs  x6, x6, x11
    adcs  x7, x7, x11
    adcs  x8, x8, x11
    adcs  x9, x9, x11
    movn  x11, #0xfca0, lsl #48      // 2p[7] = 0x035FFFFFFFFFFFFF
    adc   x10, x10, x11

    // [x11:x20] <- z = d x s0
    ldr   x21, [sp]
    MUL64x512  x11,x12,x13,x14,x15,x16,x17,x19,x20, x3,x4,x5,x6,x7,x8,x9,x10, x21, x22
    FPMUL512x512  sp, x3,x4,x5,x6,x7,x8,x9,x10, x11,x12,x13,x14,x15,x16,x17,x19,x20, x21, x22

    // c0 -> [x0] (a0's slot; a1 is still intact if c == a)
    stp   x20, x11, [x0]
    stp   x12, x13, [x0, #16]
    stp   x14, x15, [x0, #32]
    stp   x16, x17, [x0, #48]

    // [x20, x11:x19] <- z = a1 x t0
    ldp   x3, x4, [x1, #64]
    ldp   x5, x6, [x1, #80]
    ldp   x7, x8, [x1, #96]
    ldp   x9, x10, [x1, #112]
    add   x1, sp, #64                // x1 is dead after the a1 load: reuse it as the t pointer
    ldr   x21, [x1]
    MUL64x512  x20,x11,x12,x13,x14,x15,x16,x17,x19, x3,x4,x5,x6,x7,x8,x9,x10, x21, x22
    FPMUL512x512  x1, x3,x4,x5,x6,x7,x8,x9,x10, x20,x11,x12,x13,x14,x15,x16,x17,x19, x21, x22

    stp   x19, x20, [x0, #64]
    stp   x11, x12, [x0, #80]
    stp   x13, x14, [x0, #96]
    stp   x15, x16, [x0, #112]
    ldp   x21, x22, [sp, #144]
    ldp   x19, x20, [sp, #128]
    add   sp, sp, #160
    ret

//***********************************************************************
//  Field multiplication in GF(p)
//  Operation: c = a x b mod p
//  Inputs: a stored in [x1], b stored in [x2]
//  Output: c stored in [x0]
//  Register allocation: a (resident) = x3..x10;
//                       acc z0..z8 = x11..x17,x19,x20,
//                       scalar bi = x21, MULADD temp x22;
//                       the reduction borrows bi (dead there).
//***********************************************************************
.global fp_mul
.p2align 6
fp_mul:
    stp   x19, x20, [sp, #-32]!
    stp   x21, x22, [sp, #16]
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]

    // [x11:x20] <- z = a x b0
    ldr   x21, [x2]
    MUL64x512  x11,x12,x13,x14,x15,x16,x17,x19,x20, x3,x4,x5,x6,x7,x8,x9,x10, x21, x22
    FPMUL512x512  x2, x3,x4,x5,x6,x7,x8,x9,x10, x11,x12,x13,x14,x15,x16,x17,x19,x20, x21, x22

    stp   x20, x11, [x0]
    stp   x12, x13, [x0, #16]
    stp   x14, x15, [x0, #32]
    stp   x16, x17, [x0, #48]
    ldp   x21, x22, [sp, #16]
    ldp   x19, x20, [sp], #32
    ret

.global fp_sqr
.p2align 6
fp_sqr:
    mov   x2, x1
    b     fp_mul
